  @JavascriptInterface public void restoreSession(String id){new Thread(()->{int st=0;String body="";try{JSONObject saved=loadSecureSession();if(saved==null)throw new IllegalStateException("Sessão não encontrada.");Result r=request("POST","/auth/v1/token?grant_type=refresh_token",new JSONObject().put("refresh_token",saved.getString("refresh_token")),null,null);st=r.status;body=r.body;if(st>=200&&st<300)saveSecureSession(new JSONObject(body));else clearSecureSession();}catch(Exception e){clearSecureSession();body=error(e);}callback(id,st,body);}).start();}
